SELECT * FROM (SELECT "n"."nspname", "c"."relname", "a"."attname", "a"."atttypid", "a"."attnotnull" OR ("t"."typtype" = 'd' AND "t"."typnotnull") AS "attnotnull", "a"."atttypmod", "a"."attlen", "t"."typtypmod", row_number() OVER (PARTITION BY "a"."attrelid" ORDER BY "a"."attnum" NULLS LAST) AS "attnum", CASE WHEN "a"."attidentity" <> '' OR "a"."attidentity" IS NULL OR '' IS NULL THEN "a"."attidentity" END AS "attidentity", CASE WHEN "a"."attgenerated" <> '' OR "a"."attgenerated" IS NULL OR '' IS NULL THEN "a"."attgenerated" END AS "attgenerated", CAST(NULL AS STRING) AS "adsrc", "dsc"."description", "t"."typbasetype", "t"."typtype" FROM information_schema."pg_namespace" AS "n" JOIN information_schema."pg_class" AS "c" ON ("c"."relnamespace" = "n"."oid") JOIN information_schema."pg_attribute" AS "a" ON ("a"."attrelid" = "c"."oid") JOIN information_schema."pg_type" AS "t" ON ("a"."atttypid" = "t"."oid") LEFT JOIN information_schema."pg_attrdef" AS "def" ON ("a"."attrelid" = "def"."adrelid" AND "a"."attnum" = "def"."adnum") LEFT JOIN information_schema."pg_description" AS "dsc" ON ("c"."oid" = "dsc"."objoid" AND "a"."attnum" = "dsc"."objsubid") LEFT JOIN information_schema."pg_class" AS "dc" ON ("dc"."oid" = "dsc"."classoid" AND "dc"."relname" = 'pg_class') LEFT JOIN information_schema."pg_namespace" AS "dn" ON ("dc"."relnamespace" = "dn"."oid" AND "dn"."nspname" = 'pg_catalog') WHERE "c"."relkind" IN ('r', 'p', 'v', 'f', 'm') AND "a"."attnum" > 0 AND NOT "a"."attisdropped" AND "n"."nspname" LIKE 'refdb' AND "c"."relname" LIKE 'sensors') c WHERE TRUE AND "attname" LIKE '%' ORDER BY "nspname" NULLS LAST, "c"."relname" NULLS LAST, "attnum" NULLS LAST
